1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     Unit tests for the SPI interface module.
4	--!
5	--! @license    This project is released under the terms of the MIT License. See LICENSE for more details.
6	--!
7	
8	-- vunit: run_all_in_same_sim
9	
10	library ieee;
11	use ieee.std_logic_1164.all;
12	use ieee.numeric_std.all;
13	use ieee.math_real.all;
14	
15	library vunit_lib;
16	context vunit_lib.vunit_context;
17	use vunit_lib.queue_pkg.all;
18	
19	library osvvm;
20	use osvvm.RandomPkg.RandomPType;
21	
22	use work.tb_utils.all;
23	use work.utils_pkg.all;
24	
25	
26	entity tb_spi_interface is
27	    generic (
28	        runner_cfg: string := runner_cfg_default;
29	        tb_path: string
30	    );
31	end entity;
32	
33	architecture tb of tb_spi_interface is
34	    -------------------------------------------------------------
35	    -- Internal tb signals/constants
36	    -------------------------------------------------------------
37	    constant PROPAGATION_TIME: time := 1 ns;
38	    constant SIMULATION_TIMEOUT_TIME: time := 1 ms;
39	    constant ENABLE_DEBUG_PRINT: boolean := false;
40	
41	    constant SPI_CLK_FREQUENCY: real := real(50e6);
42	    constant SPI_CLK_PHASE_SHIFT: time := 0 fs;
43	
44	    constant TX_FIFO_WRITE_CLK_FREQUENCY: real := SPI_CLK_FREQUENCY; -- Same as SPI clock for simplicity
45	    constant TX_FIFO_WRITE_CLK_PHASE_SHIFT: time := 0 fs;
46	    -------------------------------------------------------------
47	
48	    -------------------------------------------------------------
49	    -- DuT signals, constants
50	    -------------------------------------------------------------
51	    constant SPI_CLK_POLARITY: bit := '0';
52	    constant SPI_CLK_PHASE: bit := '0';
53	    constant CONTROLLER_AND_NOT_PERIPHERAL: boolean := true;
54	    constant MSB_FIRST_AND_NOT_LSB: boolean := true;
55	    constant DATA_WIDTH: positive := 8;
56	    constant CHIP_COUNT: positive := 8;
57	
58	    package spi_pkg_constrained is new work.spi_pkg
59	        generic map (
60	            DATA_WIDTH => DATA_WIDTH,
61	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB
62	        );
63	    use spi_pkg_constrained.all;
64	
65	    signal spi_clk_in: std_ulogic := '0';
66	    signal rst_n: std_ulogic := '1';
67	
68	    signal selected_chips: std_ulogic_vector(CHIP_COUNT - 1 downto 0) := (others => '0');
69	
70	    -- FIFO interface signals
71	    signal tx_fifo_write_clk: std_ulogic := '0';
72	    signal tx_fifo_write_enable: std_ulogic := '0';
73	    signal tx_fifo_write_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0) := (others => '0');
74	    signal tx_fifo_write_blocked: std_ulogic;
75	    signal tx_fifo_full: std_ulogic;
76	    signal tx_fifo_empty: std_ulogic;
77	    signal tx_fifo_words_stored: natural range 0 to 2**4; -- 2**TX_FIFO_DEPTH_IN_BITS
78	
79	    -- Streaming control
80	    signal tx_trigger: std_ulogic := '0';
81	
82	    signal rx_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
83	    signal rx_data_valid: std_ulogic;
84	
85	    signal spi_clk_out: std_ulogic;
86	    signal serial_data_out: std_logic;
87	    signal serial_data_in: std_ulogic := '0';
88	    signal spi_chip_select_n: std_ulogic_vector(CHIP_COUNT - 1 downto 0);
89	
90	    signal spi_busy: std_ulogic;
91	    ------------------------------------------------------------
92	
93	    ------------------------------------------------------------
94	    -- Testbench signals
95	    ------------------------------------------------------------
96	    signal serial_data_out_expected: std_logic;
97	    signal serial_data_out_internal: std_logic;
98	    signal spi_chip_select_n_expected: spi_chip_select_n'subtype;
99	    signal spi_chip_select_n_internal: spi_chip_select_n'subtype;
100	
101	    signal loopback_enabled: boolean := false;
102	
103	    signal spi_clk_enable: std_ulogic := '1';
104	    signal tx_fifo_write_clk_enable: std_ulogic := '1';
105	    signal simulation_done: boolean := false;
106	
107	    signal received_queue: queue_t;
108	    signal spi_monitor_reset: std_ulogic := '1';
109	    ------------------------------------------------------------
110	begin
111	    ------------------------------------------------------------
112	    -- CLOCK Generation
113	    ------------------------------------------------------------
114	    generate_advanced_clock(spi_clk_in, SPI_CLK_FREQUENCY, SPI_CLK_PHASE_SHIFT, spi_clk_enable);
115	    generate_advanced_clock(tx_fifo_write_clk, TX_FIFO_WRITE_CLK_FREQUENCY, TX_FIFO_WRITE_CLK_PHASE_SHIFT, tx_fifo_write_clk_enable);
116	    ------------------------------------------------------------
117	
118	    ------------------------------------------------------------
119	    -- Loopback logic for testing full-duplex communication
120	    ------------------------------------------------------------
121	    serial_data_in <= std_ulogic(serial_data_out) when loopback_enabled else '0';
122	    ------------------------------------------------------------
123	
124	    ------------------------------------------------------------
125	    -- SPI Monitor Process - Acts as SPI Receiver using queues
126	    ------------------------------------------------------------
127	    spi_monitor: process (spi_clk_in)
128	        variable bit_index: natural range 0 to DATA_WIDTH - 1;
129	        variable captured_word: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
130	        variable receiving: boolean := false;
131	    begin
132	        if rx_active_edge(spi_clk_in, SPI_CLK_POLARITY, SPI_CLK_PHASE) then
133	            if spi_monitor_reset then
134	                reset_bit_index(bit_index);
135	                receiving := false;
136	                received_queue <= new_queue;
137	            else
138	                if and(spi_chip_select_n) = '0' then
139	                    captured_word(bit_index) := serial_data_out;
140	
141	                    if not receiving then
142	                        receiving := true;
143	                        reset_bit_index(bit_index);
144	                        debug("SPI Monitor: Started receiving");
145	                    end if;
146	
147	                    -- Process complete word
148	                    if last_bit_index(bit_index) then
149	                        push(queue => received_queue, value => captured_word);
150	                        log("SPI Monitor: Captured word " & to_integer_string(captured_word));
151	                        reset_bit_index(bit_index);
152	                    else
153	                        update_bit_index(bit_index);
154	                    end if;
155	                else
156	                    receiving := false;
157	                    reset_bit_index(bit_index);
158	                end if;
159	            end if;
160	        end if;
161	    end process;
162	    ------------------------------------------------------------
163	
164	    ------------------------------------------------------------
165	    -- Expected outputs alignment
166	    ------------------------------------------------------------
167	    expected_serial_data_out_and_chip_select_alignment: block
168	        signal spi_chip_select_n_assertion: spi_chip_select_n'subtype;
169	        signal spi_chip_select_n_deassertion: spi_chip_select_n'subtype;
170	    begin
171	        serial_data_out_alignment: process (all)
172	        begin
173	            if tx_active_edge(spi_clk_in, SPI_CLK_POLARITY, SPI_CLK_PHASE) then
174	                serial_data_out_expected <= serial_data_out_internal;
175	            end if;
176	        end process;
177	
178	        chip_select_n_alignment: process (all)
179	        begin
180	            if active_edge_chip_select_n_assertion(spi_clk_in, SPI_CLK_POLARITY) then
181	                spi_chip_select_n_assertion <= spi_chip_select_n_internal;
182	            end if;
183	
184	            if active_edge_chip_select_n_deassertion(spi_clk_in, SPI_CLK_POLARITY) then
185	                spi_chip_select_n_deassertion <= spi_chip_select_n_internal;
186	            end if;
187	
188	            spi_chip_select_n_expected <= spi_chip_select_n_assertion and spi_chip_select_n_deassertion;
189	        end process;
190	    end block;
191	    ------------------------------------------------------------
192	
193	    ------------------------------------------------------------
194	    -- VUnit
195	    ------------------------------------------------------------
196	    test_runner_watchdog(runner, SIMULATION_TIMEOUT_TIME);
197	
198	    main: process
199	    begin
200	        test_runner_setup(runner, runner_cfg);
201	        info("Starting tb_spi_interface");
202	
203	        if ENABLE_DEBUG_PRINT then
204	            show(display_handler, debug);
205	        end if;
206	
207	        wait until simulation_done;
208	        info("Simulation done, all tests passed!" & LF);
209	
210	        test_runner_cleanup(runner);
211	        wait;
212	    end process;
213	    ------------------------------------------------------------
214	
215	    ------------------------------------------------------------
216	    -- Checker
217	    ------------------------------------------------------------
218	    checker: process
219	        variable random: RandomPType;
220	        variable expected_tx_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
221	        variable expected_rx_data: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
222	        variable expected_spi_chip_select_n: spi_chip_select_n'subtype;
223	
224	        procedure wait_spi_clk_cycles(cycles: natural) is begin
225	            for i in 0 to cycles - 1 loop
226	                wait until rising_edge(spi_clk_in);
227	            end loop;
228	            wait for PROPAGATION_TIME;
229	        end procedure;
230	
231	        procedure wait_tx_spi_clk_cycles(cycles: natural) is begin
232	            for i in 0 to cycles - 1 loop
233	                wait until tx_active_edge(spi_clk_in, SPI_CLK_POLARITY, SPI_CLK_PHASE);
234	            end loop;
235	            wait for PROPAGATION_TIME;
236	        end procedure;
237	
238	        procedure wait_chip_select_n_cycles(cycles: natural) is begin
239	            for i in 0 to cycles - 1 loop
240	                wait until active_edge_chip_select_n_assertion(spi_clk_in, SPI_CLK_POLARITY);
241	            end loop;
242	            wait for PROPAGATION_TIME;
243	        end procedure;
244	
245	        procedure reset_module is begin
246	            rst_n <= '0';
247	            wait_spi_clk_cycles(5);
248	            rst_n <= '1';
249	            wait_spi_clk_cycles(5);
250	        end procedure;
251	
252	        procedure test_reset_behavior is begin
253	            info("1.0) Testing reset behavior");
254	
255	            rst_n <= '1';
256	            tx_fifo_write_enable <= '0';
257	            tx_trigger <= '0';
258	            selected_chips <= (others => '0');
259	            tx_fifo_write_data <= (others => '0');
260	
261	            spi_monitor_reset <= '1';
262	            loopback_enabled <= false;
263	            wait_spi_clk_cycles(2);
264	
265	            -- Apply reset
266	            rst_n <= '0';
267	            wait_spi_clk_cycles(2);
268	            check_equal(got => spi_busy, expected => '1', msg => "TX should be inactive during reset");
269	            check_equal(got => rx_data_valid, expected => '0', msg => "RX data valid should be inactive during reset");
270	
271	            -- Release reset
272	            rst_n <= '1';
273	            wait_spi_clk_cycles(2);
274	            check_equal(got => spi_busy, expected => '0', msg => "TX should remain inactive after reset");
275	            check_equal(got => rx_data_valid, expected => '0', msg => "RX data valid should remain inactive after reset");
276	
277	            info("Reset behavior test passed" & LF);
278	        end procedure;
279	
280	        procedure test_tx_only_operation is begin
281	            info("2.0) Testing TX-only operation with FIFO");
282	
283	            reset_module;
284	
285	            expected_tx_data := random.RandSlv(DATA_WIDTH);
286	            loopback_enabled <= false;
287	
288	            -- Load data into FIFO
289	            tx_fifo_write_data <= expected_tx_data;
290	            selected_chips <= (0 => '1', others => '0'); -- Select first chip
291	            spi_monitor_reset <= '1';
292	
293	            expected_spi_chip_select_n := (0 => '0', others => '1'); -- Only first chip should be selected
294	
295	            tx_fifo_write_enable <= '1';
296	            wait_spi_clk_cycles(1);
297	            tx_fifo_write_enable <= '0';
298	
299	            wait until not tx_fifo_empty;
300	            wait_spi_clk_cycles(1);
301	
302	            tx_trigger <= '1';
303	            wait_spi_clk_cycles(1);
304	            tx_trigger <= '0';
305	
306	            wait until spi_busy;
307	            check_equal(got => spi_busy, expected => '1', msg => "TX should be active");
308	            wait_chip_select_n_cycles(4);
309	
310	            check_equal(got => spi_chip_select_n, expected => expected_spi_chip_select_n, msg => "Chip select should be active");
311	
312	            -- Wait for transmission to complete
313	            wait_spi_clk_cycles(DATA_WIDTH + 2);
314	
315	            wait_spi_clk_cycles(2);
316	            check_equal(got => spi_busy, expected => '0', msg => "TX should be inactive after transmission");
317	            check_equal(got => and(spi_chip_select_n), expected => '1', msg => "All chip selects should be inactive after transmission");
318	
319	            info("TX-only operation test passed" & LF);
320	        end procedure;
321	
322	        procedure test_full_duplex_operation is begin
323	            info("3.0) Testing full-duplex operation (loopback) with FIFO");
324	
325	            reset_module;
326	
327	            expected_tx_data := random.RandSlv(DATA_WIDTH);
328	            expected_rx_data := expected_tx_data;
329	
330	            spi_monitor_reset <= '1';
331	            loopback_enabled <= true;
332	
333	            tx_fifo_write_data <= expected_tx_data;
334	            selected_chips <= (0 => '1', others => '0'); -- Select first chip
335	            expected_spi_chip_select_n := (0 => '0', others => '1'); -- Only first chip should be selected
336	
337	            tx_fifo_write_enable <= '1';
338	            wait_spi_clk_cycles(1);
339	            tx_fifo_write_enable <= '0';
340	
341	            wait until not tx_fifo_empty;
342	            wait_spi_clk_cycles(1);
343	
344	            tx_trigger <= '1';
345	            wait_spi_clk_cycles(1);
346	            tx_trigger <= '0';
347	
348	            wait until spi_busy;
349	            check_equal(got => spi_busy, expected => '1', msg => "TX should be active");
350	            wait_chip_select_n_cycles(4);
351	
352	            wait_spi_clk_cycles(DATA_WIDTH);
353	
354	            check_equal(got => rx_data_valid, expected => '1', msg => "RX data valid should be active after reception");
355	            check_equal(got => rx_data, expected => expected_rx_data, msg => "Received data should match transmitted data in loopback mode");
356	
357	            wait until not spi_busy;
358	
359	            loopback_enabled <= false;
360	            wait_spi_clk_cycles(1);
361	
362	            info("Full-duplex operation test passed" & LF);
363	        end procedure;
364	
365	        procedure test_multiple_single_transfers is
366	            constant REPETITION_COUNT: positive := 10; -- Number of repetitions for each transfer
367	        begin
368	            info("4.0) Testing multiple single transfers with FIFO");
369	
370	            reset_module;
371	
372	            spi_monitor_reset <= '1';
373	            loopback_enabled <= true;
374	
375	            for i in 0 to REPETITION_COUNT - 1 loop
376	                expected_tx_data := random.RandSlv(DATA_WIDTH);
377	
378	                tx_fifo_write_data <= expected_tx_data;
379	                selected_chips <= (0 => '1', others => '0'); -- Select first chip
380	
381	                tx_fifo_write_enable <= '1';
382	                wait_spi_clk_cycles(1);
383	                tx_fifo_write_enable <= '0';
384	
385	                wait until not tx_fifo_empty;
386	                wait_spi_clk_cycles(1);
387	
388	                tx_trigger <= '1';
389	                wait_spi_clk_cycles(1);
390	                tx_trigger <= '0';
391	
392	                wait until spi_busy;
393	                check_equal(got => spi_busy, expected => '1', msg => "TX should be active");
394	                wait_chip_select_n_cycles(4);
395	
396	                wait_spi_clk_cycles(DATA_WIDTH);
397	
398	                check_equal(got => rx_data_valid, expected => '1', msg => "RX data valid should be active after reception");
399	                check_equal(got => rx_data, expected => expected_tx_data, msg => "First received data should match in loopback mode");
400	
401	                wait until not spi_busy;
402	            end loop;
403	
404	            loopback_enabled <= false;
405	            wait_spi_clk_cycles(1);
406	
407	            info("Multiple transfers test passed" & LF);
408	        end procedure;
409	
410	        procedure test_multi_chip_transfers is
411	            variable active_chip_select_n_index: natural range 0 to CHIP_COUNT - 1;
412	            variable selected_chip_count: natural;
413	        begin
414	            info("5.0) Testing multi-chip transfers with FIFO");
415	
416	            reset_module;
417	
418	            spi_monitor_reset <= '1';
419	            loopback_enabled <= true;
420	
421	            -- At least 2 chips should be selected for this test
422	            selected_chips <= random.RandSlv(Min => 3, Max => 2**selected_chips'length - 1, Size => selected_chips'length);
423	
424	            -- Wait for signal assignment to take effect
425	            wait_spi_clk_cycles(1);
426	
427	            -- Count how many chips are selected
428	            selected_chip_count := 0;
429	            for i in 0 to CHIP_COUNT - 1 loop
430	                if selected_chips(i) then
431	                    selected_chip_count := selected_chip_count + 1;
432	                end if;
433	            end loop;
434	
435	            for i in 0 to selected_chip_count - 1 loop
436	                expected_tx_data := random.RandSlv(DATA_WIDTH);
437	                tx_fifo_write_data <= expected_tx_data;
438	                tx_fifo_write_enable <= '1';
439	                wait_spi_clk_cycles(1);
440	                tx_fifo_write_enable <= '0';
441	            end loop;
442	
443	            wait_spi_clk_cycles(5);
444	
445	            tx_trigger <= '1';
446	            wait_spi_clk_cycles(1);
447	            tx_trigger <= '0';
448	
449	            wait until spi_busy;
450	            check_equal(got => spi_busy, expected => '1', msg => "TX should be active");
451	
452	            -- Check each selected chip gets its transmission in the order they appear
453	            for i in 0 to CHIP_COUNT - 1 loop
454	                if selected_chips(i) then
455	                    active_chip_select_n_index := i;
456	
457	                    -- Wait for this specific chip to be selected
458	                    expected_spi_chip_select_n := (others => '1');
459	                    expected_spi_chip_select_n(active_chip_select_n_index) := '0';
460	
461	                    -- Wait until this chip is actually selected OR transmission ends
462	                    loop
463	                        wait_spi_clk_cycles(1);
464	                        exit when spi_chip_select_n = expected_spi_chip_select_n or spi_busy = '0';
465	                    end loop;
466	
467	                    if spi_busy then
468	                        check_equal(got => spi_chip_select_n, expected => expected_spi_chip_select_n, msg => "spi_chip_select_n - Chip " & to_string(i) & " should be active");
469	
470	                        -- Wait for the data transmission to complete for this chip
471	                        wait_tx_spi_clk_cycles(DATA_WIDTH);
472	
473	                        -- Wait for chip to be deselected before checking next chip
474	                        loop
475	                            wait_spi_clk_cycles(1);
476	                            exit when spi_chip_select_n /= expected_spi_chip_select_n or spi_busy = '0';
477	                        end loop;
478	                        wait_spi_clk_cycles(1);
479	                    else
480	                        debug("Transmission ended before chip " & to_string(i) & " was selected");
481	                        exit; -- Exit the loop if transmission has ended
482	                    end if;
483	                end if;
484	            end loop;
485	
486	            loopback_enabled <= false;
487	            wait_spi_clk_cycles(2);
488	
489	            info("Multi-chip transfers test passed" & LF);
490	        end procedure;
491	
492	        procedure test_multi_word_fifo_multi_chip_streaming is
493	            constant WORD_COUNT_PER_CHIP: positive := 5;
494	
495	            variable expected_queue: queue_t;
496	            variable test_word: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
497	            variable received_word: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
498	            variable expected_word: std_ulogic_vector(DATA_WIDTH - 1 downto 0);
499	        begin
500	            info("Test 6.0) Multi-word FIFO streaming across multiple chips");
501	
502	            reset_module;
503	
504	            expected_queue := new_queue;
505	
506	            spi_monitor_reset <= '1';
507	            selected_chips <= (0 => '1', 2 => '1', 4 => '1', others => '0');
508	            wait_spi_clk_cycles(1);
509	            spi_monitor_reset <= '0';
510	
511	            for chip_idx in selected_chips'range loop
512	                if selected_chips(chip_idx) then
513	                    for word_idx in 0 to WORD_COUNT_PER_CHIP - 1 loop
514	                        test_word := random.RandSlv(Size => DATA_WIDTH);
515	                        push(queue => expected_queue, value => test_word);
516	                        tx_fifo_write_data <= test_word;
517	                        tx_fifo_write_enable <= '1';
518	                        wait_spi_clk_cycles(1);
519	                    end loop;
520	                end if;
521	            end loop;
522	
523	            tx_fifo_write_enable <= '0';
524	
525	            -- Wait for FIFO timing
526	            wait_spi_clk_cycles(5);
527	
528	            tx_trigger <= '1';
529	            wait_spi_clk_cycles(1);
530	            tx_trigger <= '0';
531	            wait until and(spi_chip_select_n);
532	
533	            while not is_empty(expected_queue) and not is_empty(received_queue) loop
534	                received_word := pop_std_ulogic_vector(queue => received_queue);
535	                expected_word := pop_std_ulogic_vector(queue => expected_queue);
536	                check_equal(got => received_word, expected => expected_word);
537	            end loop;
538	
539	            wait until not spi_busy;
540	            wait_chip_select_n_cycles(2); -- Give some time after last chip deselection
541	
542	            check_equal(got => spi_busy, expected => '0', msg => "TX should be inactive after transmission");
543	            check_equal(got => and(spi_chip_select_n), expected => '1', msg => "All chip selects should be deasserted");
544	
545	            info("Multi-word multi-chip FIFO streaming test passed" & LF);
546	        end procedure;
547	    begin
548	        random.InitSeed(tb_path & random'instance_name);
549	
550	        -- Don't remove, else VUnit will not run the test suite
551	        wait_spi_clk_cycles(1);
552	
553	        while test_suite loop
554	            if run("test_reset_behavior") then
555	                test_reset_behavior;
556	            elsif run("test_tx_only_operation") then
557	                test_tx_only_operation;
558	            elsif run("test_full_duplex_operation") then
559	                test_full_duplex_operation;
560	            elsif run("test_multiple_single_transfers") then
561	                test_multiple_single_transfers;
562	            elsif run("test_multi_chip_transfers") then
563	                test_multi_chip_transfers;
564	            elsif run("test_multi_word_fifo_multi_chip_streaming") then
565	                test_multi_word_fifo_multi_chip_streaming;
566	            else
567	                assert false report "No test has been run!" severity failure;
568	            end if;
569	        end loop;
570	
571	        simulation_done <= true;
572	    end process;
573	    ------------------------------------------------------------
574	
575	    ------------------------------------------------------------
576	    -- DUT instantiation
577	    ------------------------------------------------------------
578	    DUT: entity work.spi_interface
579	        generic map (
580	            SPI_CLK_POLARITY => SPI_CLK_POLARITY,
581	            SPI_CLK_PHASE => SPI_CLK_PHASE,
582	            SPI_CHIPS_AMOUNT => CHIP_COUNT,
583	            DATA_WIDTH => DATA_WIDTH,
584	            CONTROLLER_AND_NOT_PERIPHERAL => CONTROLLER_AND_NOT_PERIPHERAL,
585	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB,
586	            ENABLE_INTERNAL_CLOCK_GATING => true,
587	            USE_XILINX_CLK_GATE_AND_NOT_INTERNAL => false,
588	            TX_FIFO_DEPTH_IN_BITS => 4
589	        )
590	        port map (
591	            spi_clk_in => spi_clk_in,
592	            rst_n => rst_n,
593	            selected_chips => selected_chips,
594	
595	            -- FIFO interface
596	            tx_fifo_write_clk => spi_clk_in,
597	            tx_fifo_write_enable => tx_fifo_write_enable,
598	            tx_fifo_write_data => tx_fifo_write_data,
599	            tx_fifo_write_blocked => tx_fifo_write_blocked,
600	            tx_fifo_full => tx_fifo_full,
601	            tx_fifo_empty => tx_fifo_empty,
602	            tx_fifo_words_stored => tx_fifo_words_stored,
603	
604	            -- Streaming control
605	            tx_trigger => tx_trigger,
606	            spi_busy => spi_busy,
607	
608	            rx_data => rx_data,
609	            rx_data_valid => rx_data_valid,
610	            spi_clk_out => spi_clk_out,
611	            serial_data_out => serial_data_out,
612	            serial_data_in => serial_data_in,
613	            spi_chip_select_n => spi_chip_select_n
614	        );
615	    ------------------------------------------------------------
616	end architecture;
