1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     This module describes the SPI Communication Interface with customisable parameters
4	--! @details:   It integrates both SPI TX and RX functionalities.
5	--!             The interface allows for configuration of clock polarity, phase, and data transmission order.
6	--!             It supports both controller and peripheral modes.
7	--!
8	--! @note:      The SPI_CLK_POLARITY and SPI_CLK_PHASE parameters determine the clock behavior.
9	--! @note:      Vendor-specific clock handling recommendations:
10	--!
11	--!             For Xilinx FPGAs:
12	--!             - Set ENABLE_INTERNAL_CLOCK_GATING to true
13	--!             - For global clock networks, set USE_XILINX_CLK_GATE_AND_NOT_INTERNAL to true to use BUFGCE
14	--!             - For local clock networks, USE_XILINX_CLK_GATE_AND_NOT_INTERNAL can be false for regular gating
15	--!
16	--!             For Intel/Altera FPGAs:
17	--!             - Set ENABLE_INTERNAL_CLOCK_GATING to false to avoid direct clock gating
18	--!             - Always set USE_XILINX_CLK_GATE_AND_NOT_INTERNAL to false
19	--!             - Instead of clock gating:
20	--!               1. Use the enable pin on Intel PLLs to control clock generation at the source
21	--!               2. Use register enable pins throughout your design instead of gating the clock
22	--!               3. If implementing the SPI controller, consider using clock enables at registers
23	--!                  rather than gating the SPI clock output
24	--!
25	--! @license This project is released under the terms of the MIT License. See LICENSE for more details.
26	--!
27	
28	library ieee;
29	use ieee.std_logic_1164.all;
30	use ieee.numeric_std.all;
31	
32	use work.utils_pkg.all;
33	
34	entity spi_interface is
35	    generic (
36	        SPI_CLK_POLARITY: bit := '0'; -- Clock polarity
37	        SPI_CLK_PHASE: bit := '0'; -- Clock phase
38	        SPI_CHIPS_AMOUNT: natural := 1; -- Number of SPI chips
39	        DATA_WIDTH: natural := 8; -- Width of the data bus
40	        CONTROLLER_AND_NOT_PERIPHERAL: boolean := true;
41	        MSB_FIRST_AND_NOT_LSB: boolean := true;
42	        ENABLE_INTERNAL_CLOCK_GATING: boolean := true;
43	        USE_XILINX_CLK_GATE_AND_NOT_INTERNAL: boolean := false;
44	        TX_FIFO_DEPTH_IN_BITS: natural := 4 -- Set to 0 for single-word mode
45	    );
46	    port (
47	        spi_clk_in: in std_ulogic;
48	        rst_n: in std_ulogic;
49	
50	        selected_chips: in std_ulogic_vector(SPI_CHIPS_AMOUNT - 1 downto 0);
51	
52	        tx_fifo_write_clk: in std_ulogic;
53	        tx_fifo_write_enable: in std_ulogic;
54	        tx_fifo_write_data: in std_ulogic_vector(DATA_WIDTH - 1 downto 0);
55	        tx_fifo_write_blocked: out std_ulogic;
56	        tx_fifo_full: out std_ulogic;
57	        tx_fifo_empty: out std_ulogic;
58	        tx_fifo_words_stored: out natural range 0 to 2**TX_FIFO_DEPTH_IN_BITS;
