74	architecture behavioural of spi_interface is
75	    constant CHIP_INDEX_OUT_OF_RANGE: natural := selected_chips'length;
76	    signal current_chip_index: natural range 0 to CHIP_INDEX_OUT_OF_RANGE;
77	
78	    -- FSM state
