199	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB,
200	            ENABLE_INTERNAL_CLOCK_GATING => ENABLE_INTERNAL_CLOCK_GATING,
201	            USE_XILINX_CLK_GATE_AND_NOT_INTERNAL => USE_XILINX_CLK_GATE_AND_NOT_INTERNAL
202	        )
203	        port map (
204	            spi_clk_in => spi_clk_in,
205	            rst_n => rst_n,
206	            tx_data => tx_data,
207	            tx_data_valid => tx_data_valid,
208	            tx_data_ack => tx_data_ack,
209	            spi_clk_out => spi_clk_out,
210	            serial_data_out => serial_data_out,
211	            spi_chip_select_n => spi_chip_select_n_internal,
212	            tx_is_ongoing => tx_is_ongoing
213	        );
