217	            SPI_CLK_POLARITY => SPI_CLK_POLARITY,
218	            SPI_CLK_PHASE => SPI_CLK_PHASE,
219	            DATA_WIDTH => DATA_WIDTH,
220	            MSB_FIRST_AND_NOT_LSB => MSB_FIRST_AND_NOT_LSB
221	        )
