1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     This module is a wrapper for the async FIFO of Xilinx technology.
4	--! @details:   Based on Simulation and Synthesis Techniques for Asynchronous FIFO Design by Clifford E. Cummings, Sunburst Design, Inc.
5	--!
6	--! @license This project is released under the terms of the MIT License. See LICENSE for more details.
7	--!
8	
9	library ieee;
10	use ieee.std_logic_1164.all;
11	use ieee.numeric_std.all;
12	
13	use work.utils_pkg.all;
14	use work.memories_pkg.all;
15	
16	entity fifo_async is
17	    generic (
18	        FIFO_DEPTH_IN_BITS: natural range 0 to to_bits(natural'high) := 2;
19	        CDC_SYNC_STAGES: positive := 2;
20	        INTEL_DEVICE_FAMILY: string := "Cyclone V"; -- Change this to your target Intel device family
21	        INTEL_CLOCKS_ARE_SYNCHRONIZED: boolean := false
22	    );
23	    port (
24	        aclr: in std_ulogic;
25	        write_clk: in std_ulogic;
26	        read_clk: in std_ulogic;
27	        write_enable: in std_ulogic;
28	        write_data: in std_ulogic_vector;
29	        read_enable: in std_ulogic;
30	        read_data: out std_ulogic_vector;
31	        read_data_valid: out std_ulogic;
32	        full: out std_ulogic;
33	        empty: out std_ulogic;
34	        words_stored: out natural range 0 to 2**FIFO_DEPTH_IN_BITS;
35	
36	        -- Reset read pointer for data replay (keeps write pointer intact)
37	        reset_read_pointer: in std_ulogic := '0'
38	    );
39	
40	    constant FIFO_DEPTH: natural := 2**FIFO_DEPTH_IN_BITS;
41	    constant ADDRESS_WIDTH: natural := to_bits(FIFO_DEPTH);
42	end entity;
43	
44	library xpm;
45	use xpm.vcomponents.all;
46	
47	--!
48	--! @brief: This module is a Xilinx technology specific FIFO memory block.
49	--! @note:  This module is a wrapper for the xpm_fifo_async module.
50	--! @note:  Use this primarily for Xilinx technology.
51	--!
52	architecture xilinx_behavioural_async_fifo of fifo_async is
53	    signal prog_full_unconnected: std_ulogic;
54	    signal prog_empty_unconnected: std_ulogic;
55	    signal wr_data_count: std_ulogic_vector(ADDRESS_WIDTH downto 0);
56	    signal rd_data_count_unconnected: std_ulogic_vector(0 downto 0);
57	    signal wr_ack_unconnected: std_ulogic;
58	    signal overflow_unconnected: std_ulogic;
59	    signal underflow_unconnected: std_ulogic;
60	    signal wr_rst_busy_unconnected: std_ulogic;
61	    signal rd_rst_busy_unconnected: std_ulogic;
62	    signal almost_full_unconnected: std_ulogic;
63	    signal almost_empty_unconnected: std_ulogic;
64	    signal sbiterr_unconnected: std_ulogic;
65	    signal dbiterr_unconnected: std_ulogic;
66	begin
67	    words_stored <= to_integer(unsigned(wr_data_count));
68	    xpm_fifo_inst: xpm_fifo_async
69	        generic map (
70	            FIFO_MEMORY_TYPE => "auto",
71	            FIFO_WRITE_DEPTH => FIFO_DEPTH,
72	            CDC_SYNC_STAGES => CDC_SYNC_STAGES,
73	            CASCADE_HEIGHT => 0,
74	            WRITE_DATA_WIDTH => write_data'length,
75	            READ_MODE => "std",
76	            FIFO_READ_LATENCY => 1,
77	            FULL_RESET_VALUE => 0,
78	            USE_ADV_FEATURES => "0707",
79	            READ_DATA_WIDTH => read_data'length,
80	            WR_DATA_COUNT_WIDTH => wr_data_count'length,
81	            PROG_FULL_THRESH => 10,
82	            RD_DATA_COUNT_WIDTH => rd_data_count_unconnected'length,
83	            PROG_EMPTY_THRESH => 10,
84	            DOUT_RESET_VALUE => "0",
85	            ECC_MODE => "no_ecc",
86	            SIM_ASSERT_CHK => 0,
87	            RELATED_CLOCKS => 0,
88	            WAKEUP_TIME => 0
89	        )
90	        port map (
91	            sleep => '0',
92	            rst => aclr,
93	            wr_clk => write_clk,
94	            wr_en => write_enable,
95	            din => write_data,
96	            full => full,
97	            prog_full => prog_full_unconnected,
98	            wr_data_count => wr_data_count,
99	            overflow => overflow_unconnected,
100	            wr_rst_busy => wr_rst_busy_unconnected,
101	            almost_full => almost_full_unconnected,
102	            wr_ack => wr_ack_unconnected,
103	            rd_en => read_enable and not reset_read_pointer,
