1	--!
2	--! @author:    N. Selvarajah
3	--! @brief:     This module describes the SPI TX part of the SPI communication interface.
4	--!
5	--! @note:      The SPI_CLK_POLARITY and SPI_CLK_PHASE parameters determine the clock behavior.
6	--! @note:      Vendor-specific clock handling recommendations:
7	--!
8	--!             For Xilinx FPGAs:
9	--!             - Set ENABLE_INTERNAL_CLOCK_GATING to true
10	--!             - For global clock networks, set USE_XILINX_CLK_GATE_AND_NOT_INTERNAL to true to use BUFGCE
11	--!             - For local clock networks, USE_XILINX_CLK_GATE_AND_NOT_INTERNAL can be false for regular gating
12	--!
13	--!             For Intel/Altera FPGAs:
14	--!             - Set ENABLE_INTERNAL_CLOCK_GATING to false to avoid direct clock gating
15	--!             - Always set USE_XILINX_CLK_GATE_AND_NOT_INTERNAL to false
16	--!             - Instead of clock gating:
17	--!               1. Use the enable pin on Intel PLLs to control clock generation at the source
18	--!               2. Use register enable pins throughout your design instead of gating the clock
19	--!               3. If implementing the SPI controller, consider using clock enables at registers
20	--!                  rather than gating the SPI clock output
21	--!
22	--! @license This project is released under the terms of the MIT License. See LICENSE for more details.
23	--!
24	
25	library ieee;
26	use ieee.std_logic_1164.all;
27	use ieee.numeric_std.all;
28	
29	use work.utils_pkg.all;
30	
31	entity spi_tx is
32	    generic (
33	        SPI_CLK_POLARITY: bit := '0'; -- Clock polarity
34	        SPI_CLK_PHASE: bit := '0'; -- Clock phase
35	        DATA_WIDTH: natural := 8;
36	        CONTROLLER_AND_NOT_PERIPHERAL: boolean := true;
37	        MSB_FIRST_AND_NOT_LSB: boolean := true;
38	        ENABLE_INTERNAL_CLOCK_GATING: boolean := true;
39	        USE_XILINX_CLK_GATE_AND_NOT_INTERNAL: boolean := false
40	    );
41	    port (
42	        spi_clk_in: in std_ulogic;
43	        rst_n: in std_ulogic;
44	
45	        tx_data: in std_ulogic_vector(DATA_WIDTH - 1 downto 0);
46	        tx_data_valid: in std_ulogic;
47	        tx_data_ack: out std_ulogic;
48	
49	        spi_clk_out: out std_ulogic;
50	        serial_data_out: out std_logic; -- For tri-state output
51	        spi_chip_select_n: inout std_ulogic;
52	
53	        tx_is_ongoing: out std_ulogic
54	    );
55	end entity;
56	
57	architecture behavioural of spi_tx is
58	    package spi_pkg_constrained is new work.spi_pkg
